/**
 * Reminder document store used by the local control plane
 * (`<stateRoot>/control-plane/reminders/`).
 *
 * Anonymous `run` / function `until` handlers are not serializable — they live
 * only in the in-memory {@link ReminderRunner} registry. Named `handler` +
 * `args` and prompt-form reminders survive restart (handlers resolve from
 * `agent/reminders/` on every fire).
 */
import { mkdir, readdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { describeErrorCode } from "./describe-error.js";
import { isRecord } from "./is-record.js";
export const REMINDER_SNAPSHOT_VERSION = 1;
/** Narrow a sink value to a {@link ReminderRecord} (startup hydrate). */
export function isReminderRecord(value) {
    if (!isRecord(value)) {
        return false;
    }
    return (value.version === REMINDER_SNAPSHOT_VERSION &&
        typeof value.id === "string" &&
        value.id !== "" &&
        typeof value.purpose === "string" &&
        typeof value.channelId === "string" &&
        typeof value.continuationToken === "string" &&
        typeof value.scheduleKind === "string" &&
        typeof value.scheduleValue === "string" &&
        typeof value.status === "string" &&
        typeof value.nextFireAtMs === "number" &&
        Number.isFinite(value.nextFireAtMs));
}
export class ReminderStore {
    constructor(rootDir) {
        this.rootDir = rootDir;
    }
    filePath(id) {
        return join(this.rootDir, `${id}.json`);
    }
    async ensureRoot() {
        await mkdir(this.rootDir, { recursive: true });
    }
    async list() {
        await this.ensureRoot();
        let names;
        try {
            names = await readdir(this.rootDir);
        }
        catch {
            return [];
        }
        const records = [];
        for (const name of names) {
            if (!name.endsWith(".json"))
                continue;
            const record = await this.get(name.slice(0, -".json".length));
            if (record !== undefined) {
                records.push(record);
            }
        }
        return records;
    }
    async listArmed() {
        const all = await this.list();
        // Treat in-flight claims as still armed for restart / listing purposes.
        return all.filter((r) => r.status === "armed" || r.status === "firing");
    }
    async get(id) {
        try {
            const raw = await readFile(this.filePath(id), "utf8");
            const parsed = JSON.parse(raw);
            if (!isReminderRecord(parsed) || parsed.id !== id) {
                return undefined;
            }
            return parsed;
        }
        catch (error) {
            if (describeErrorCode(error) === "ENOENT") {
                return undefined;
            }
            return undefined;
        }
    }
    async save(record) {
        await this.ensureRoot();
        const path = this.filePath(record.id);
        const tmp = `${path}.${process.pid}.${Date.now()}.tmp`;
        const body = `${JSON.stringify(record, null, 2)}\n`;
        try {
            await writeFile(tmp, body, "utf8");
            await rename(tmp, path);
        }
        catch (error) {
            await rm(tmp, { force: true }).catch(() => { });
            throw error;
        }
    }
    async delete(id) {
        await rm(this.filePath(id), { force: true });
    }
}
